#!/bin/bash
# Codex SubagentStart hook — generated by scripts/gen-harness-codex.ts, do not edit.
# Hands the dinopowers wrapper routing table (scripts/wrapper-routing.txt) to the
# subagent as hookSpecificOutput.additionalContext. Nothing here fails the hook.

cat > /dev/null
ROOT="${PLUGIN_ROOT:-$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)}"
CONTEXT=$(cat "$ROOT/scripts/wrapper-routing.txt" 2>/dev/null)
if [ -z "$CONTEXT" ]; then
  exit 0
fi

jq -n --arg context "$CONTEXT" '{
  hookSpecificOutput: {
    hookEventName: "SubagentStart",
    additionalContext: $context
  }
}'
exit 0
